COPY "public"."certificate_templates" ("id", "name", "description", "html_template", "css_template", "logo_url", "background_url", "primary_color", "secondary_color", "active", "created_at", "updated_at") FROM stdin;
41111111-1111-1111-1111-111111111111	Template Cyberpunk	Template ottimizzato e ridimensionato per formato A4 Landscape (297x210mm) in stile Cyberpunk, con spaziature compatte per garantire la perfetta visualizzazione di tutti i testi.	<div class="certificate-container">\r\n  <div class="bg-shape shape-1"></div>\r\n  <div class="bg-shape shape-2"></div>\r\n  <div class="certificate-card">\r\n    <div class="header">\r\n      <div class="logo-wrapper">\r\n        <img src="{{logoUrl}}" alt="Logo Piattaforma" class="logo" />\r\n      </div>\r\n      <div class="badge-official">ATTESTATO DI MERITO</div>\r\n    </div>\r\n\r\n    <div class="body">\r\n      <p class="tagline">Si attesta con la presente che lo studente</p>\r\n      <h1 class="student-name">{{studentName}}</h1>\r\n      <p class="description">ha completato con successo e profitto il percorso formativo</p>\r\n      <h2 class="course-title">{{courseTitle}}</h2>\r\n      <div class="score-container">\r\n        <span class="score-label">Valutazione Finale</span>\r\n        <span class="score-value">{{score}}%</span>\r\n      </div>\r\n    </div>\r\n\r\n    <div class="footer">\r\n      <div class="footer-block">\r\n        <p class="label">Data di Rilascio</p>\r\n        <p class="value">{{date}}</p>\r\n      </div>\r\n\r\n      <div class="footer-block signature-block">\r\n        <div class="sig-line"></div>\r\n        <p class="sig-name">Prof. Giuseppe Carnabuci</p>\r\n        <p class="sig-title">Direttore Didattico - GCProf AI Academy</p>\r\n      </div>\r\n\r\n      <div class="footer-block">\r\n        <p class="label">ID Certificato</p>\r\n        <p class="value">{{certificateNumber}}</p>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>	@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;700;900&family=Rajdhani:wght@400;500;600;700&display=swap');\r\n\r\n/* Impostazioni di stampa per A4 Orizzontale (Landscape) */\r\n@page {\r\n  size: A4 landscape;\r\n  margin: 0;\r\n}\r\n\r\nbody {\r\n  margin: 0;\r\n  padding: 0;\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n  min-height: 100vh;\r\n  background: #050505; \r\n}\r\n\r\n.certificate-container {\r\n  position: relative;\r\n  width: 297mm;\r\n  height: 210mm;\r\n  background-color: #0b0c10;\r\n  /* Pattern a griglia stile Cyberpunk */\r\n  background-image: \r\n    linear-gradient(rgba(0, 243, 255, 0.07) 1px, transparent 1px),\r\n    linear-gradient(90deg, rgba(0, 243, 255, 0.07) 1px, transparent 1px);\r\n  background-size: 20px 20px;\r\n  box-sizing: border-box;\r\n  overflow: hidden;\r\n  font-family: 'Rajdhani', sans-serif;\r\n  color: #c5c6c7;\r\n  padding: 10mm;\r\n  box-shadow: 0 0 50px rgba(0, 243, 255, 0.1); \r\n}\r\n\r\n/* Bagliori al neon sullo sfondo */\r\n.bg-shape {\r\n  position: absolute;\r\n  z-index: 1;\r\n  border-radius: 50%;\r\n  filter: blur(85px);\r\n  opacity: 0.45;\r\n}\r\n.shape-1 {\r\n  width: 400px;\r\n  height: 400px;\r\n  background: #ff007f; /* Neon Magenta */\r\n  top: -100px;\r\n  left: -100px;\r\n}\r\n.shape-2 {\r\n  width: 450px;\r\n  height: 450px;\r\n  background: #00f3ff; /* Neon Cyan */\r\n  bottom: -150px;\r\n  right: -100px;\r\n}\r\n\r\n.certificate-card {\r\n  position: relative;\r\n  z-index: 2;\r\n  background: rgba(11, 12, 16, 0.9);\r\n  padding: 15mm 25mm;\r\n  border-radius: 4px;\r\n  /* Bordo illuminato al neon */\r\n  border: 1px solid rgba(0, 243, 255, 0.5);\r\n  border-top: 6px solid #ff007f;\r\n  border-bottom: 6px solid #00f3ff;\r\n  box-shadow: 0 0 25px rgba(0, 243, 255, 0.15), inset 0 0 20px rgba(255, 0, 127, 0.05);\r\n  text-align: center;\r\n  height: 100%;\r\n  box-sizing: border-box;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n}\r\n\r\n/* Watermark olografico */\r\n.certificate-card::after {\r\n  content: 'GCPROF-ACADEMY.COM';\r\n  position: absolute;\r\n  top: 50%;\r\n  left: 50%;\r\n  transform: translate(-50%, -50%) rotate(-20deg);\r\n  font-size: 4.5rem;\r\n  font-family: 'Orbitron', sans-serif;\r\n  color: rgba(0, 243, 255, 0.03);\r\n  font-weight: 900;\r\n  white-space: nowrap;\r\n  pointer-events: none;\r\n  z-index: 0;\r\n  letter-spacing: 6px;\r\n  text-shadow: 0 0 10px rgba(0, 243, 255, 0.05);\r\n}\r\n\r\n.header, .body, .footer {\r\n  position: relative;\r\n  z-index: 10;\r\n}\r\n\r\n.header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n}\r\n\r\n.logo-wrapper {\r\n  display: flex;\r\n  align-items: center;\r\n}\r\n.logo {\r\n  max-height: 75px;\r\n  width: auto;\r\n  object-fit: contain;\r\n  filter: drop-shadow(0 0 10px rgba(0, 243, 255, 0.6));\r\n}\r\n\r\n.badge-official {\r\n  background: rgba(0, 243, 255, 0.1);\r\n  color: #00f3ff;\r\n  padding: 0.6rem 1.5rem;\r\n  border-radius: 2px;\r\n  border: 1px solid #00f3ff;\r\n  font-family: 'Orbitron', sans-serif;\r\n  font-weight: 700;\r\n  font-size: 0.85rem;\r\n  letter-spacing: 2px;\r\n  text-transform: uppercase;\r\n  box-shadow: 0 0 15px rgba(0, 243, 255, 0.3);\r\n  text-shadow: 0 0 5px rgba(0, 243, 255, 0.5);\r\n}\r\n\r\n.body {\r\n  margin: 5px 0;\r\n}\r\n\r\n.tagline {\r\n  color: #f2a900; /* Cyber Yellow */\r\n  font-family: 'Orbitron', sans-serif;\r\n  font-size: 0.9rem;\r\n  text-transform: uppercase;\r\n  letter-spacing: 3px;\r\n  margin-bottom: 0.4rem;\r\n  font-weight: 600;\r\n}\r\n\r\n.student-name {\r\n  font-family: 'Orbitron', sans-serif;\r\n  font-size: 3rem;\r\n  color: #ffffff;\r\n  margin: 0.2rem 0 0.6rem;\r\n  font-weight: 900;\r\n  text-transform: uppercase;\r\n  letter-spacing: 2px;\r\n  text-shadow: 2px 2px 0px rgba(255, 0, 127, 0.8), -2px -2px 0px rgba(0, 243, 255, 0.8);\r\n}\r\n\r\n.description {\r\n  color: #c5c6c7;\r\n  font-size: 1.1rem;\r\n  margin-bottom: 0.3rem;\r\n  font-weight: 500;\r\n}\r\n\r\n.course-title {\r\n  font-family: 'Orbitron', sans-serif;\r\n  font-size: 1.8rem;\r\n  color: #00f3ff;\r\n  font-weight: 700;\r\n  margin: 0.4rem 0 1rem;\r\n  line-height: 1.2;\r\n  text-transform: uppercase;\r\n  letter-spacing: 1px;\r\n  text-shadow: 0 0 10px rgba(0, 243, 255, 0.4);\r\n}\r\n\r\n.score-container {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  background: rgba(255, 0, 127, 0.05);\r\n  padding: 0.5rem 2rem;\r\n  border-radius: 2px;\r\n  border: 1px solid #ff007f;\r\n  box-shadow: 0 0 15px rgba(255, 0, 127, 0.2);\r\n}\r\n.score-label {\r\n  color: #c5c6c7;\r\n  font-weight: 600;\r\n  font-size: 0.85rem;\r\n  text-transform: uppercase;\r\n  letter-spacing: 2px;\r\n  font-family: 'Orbitron', sans-serif;\r\n}\r\n.score-value {\r\n  color: #ff007f;\r\n  font-family: 'Orbitron', sans-serif;\r\n  font-size: 1.5rem;\r\n  font-weight: 800;\r\n  text-shadow: 0 0 12px rgba(255, 0, 127, 0.6);\r\n}\r\n\r\n.footer {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-end;\r\n  padding-top: 1rem;\r\n  border-top: 1px dashed rgba(0, 243, 255, 0.3);\r\n}\r\n\r\n.footer-block {\r\n  flex: 1;\r\n  text-align: center;\r\n}\r\n.footer-block .label {\r\n  color: #f2a900;\r\n  font-family: 'Orbitron', sans-serif;\r\n  font-size: 0.75rem;\r\n  text-transform: uppercase;\r\n  letter-spacing: 2px;\r\n  margin-bottom: 0.3rem;\r\n  font-weight: 600;\r\n}\r\n.footer-block .value {\r\n  color: #ffffff;\r\n  font-weight: 700;\r\n  font-size: 1rem;\r\n  letter-spacing: 1px;\r\n}\r\n\r\n.signature-block {\r\n  flex: 1.5;\r\n  padding: 0 1.5rem;\r\n}\r\n.sig-line {\r\n  width: 85%;\r\n  height: 2px;\r\n  background: #00f3ff;\r\n  margin: 0 auto 0.5rem;\r\n  box-shadow: 0 0 8px rgba(0, 243, 255, 0.8);\r\n}\r\n.sig-name {\r\n  font-family: 'Orbitron', sans-serif;\r\n  font-size: 1.15rem;\r\n  font-weight: 700;\r\n  color: #ffffff;\r\n  margin: 0 0 0.2rem;\r\n  text-shadow: 0 0 5px rgba(255, 255, 255, 0.3);\r\n}\r\n.sig-title {\r\n  font-size: 0.85rem;\r\n  color: #ff007f;\r\n  font-weight: 700;\r\n  margin: 0;\r\n  text-transform: uppercase;\r\n  letter-spacing: 1px;\r\n}	/gcprof-ai-academy_logo_01.png	\N	#00f3ff	#f